import { useSelector } from 'react-redux';
import { selectDarkMode } from '../store/slices/uiSlice';

/**
 * Returns a `t(darkClass, lightClass)` helper and the raw darkMode boolean.
 * Usage:  const { t, dark } = useTheme();
 *         className={t('text-white', 'text-black')}
 */
export function useTheme() {
  const dark = useSelector(selectDarkMode);
  const t = (darkClass, lightClass) => (dark ? darkClass : lightClass);

  // Convenient grouped tokens
  const tokens = {
    bg:      t('bg-[#1B1212]',  'bg-[#f8f7ff]'),
    sidebar: t('bg-[#1B1212]',  'bg-[#f0f0fa]'),
    chat:    t('bg-[#1B1212]',  'bg-white'),
    card:    t('bg-[#251A1A]',  'bg-white'),
    input:   t('bg-[#2A1D1D]',  'bg-[#f4f4fc]'),
    border:  t('border-[#3A2929]', 'border-[#e0e0f0]'),
    text:    t('text-[#e8e8f0]', 'text-[#1a1a2e]'),
    muted:   'text-[#7878a0]',
    hover:   t('hover:bg-[#2A1D1D]', 'hover:bg-[#eeeeff]'),
    msgBot:  t('bg-[#251A1A]',  'bg-[#f3f3ff]'),
    // raw hex values (for inline styles)
    textHex:   t('#e8e8f0', '#1a1a2e'),
    mutedHex:  '#7878a0',
    borderHex: t('#3A2929', '#e0e0f0'),
    inputHex:  t('#2A1D1D', '#f4f4fc'),
    hoverHex:  t('#2A1D1D', '#eeeeff'),
    bgHex:     t('#1B1212', '#f8f7ff'),
    sidebarHex:t('#1B1212', '#f0f0fa'),
    chatHex:   t('#1B1212', '#ffffff'),
    cardHex:   t('#251A1A', '#ffffff'),
    msgBotHex: t('#251A1A', '#f3f3ff'),
  };

  return { dark, t, ...tokens };
}
